6	export default function App() {
7	  const [token, setToken] = useState(null);
8	  const [error, setError] = useState(null);
9	  const [booting, setBooting] = useState(true);
10	
11	  // Surface an OAuth ?error from the callback redirect, then clean the URL.
12	  useEffect(() => {
13	    const params = new URLSearchParams(window.location.search);
14	    const e = params.get("error");
15	    if (e) {
16	      setError(e);
17	      window.history.replaceState({}, "", "/");
18	    }
19	  }, []);
20	
21	  // Bootstrap: exchange the session cookie for an access token.
22	  useEffect(() => {
23	    let cancelled = false;
24	    if (import.meta.env.DEV) console.info("[app] bootstrapping session");
25	    refreshAccessToken()
26	      .then((t) => {
27	        if (cancelled) return;
28	        if (import.meta.env.DEV) console.info("[app] session restored");
29	        setToken(t);
30	      })
31	      .catch(() => {
32	        if (import.meta.env.DEV)
33	          console.info("[app] no active session, showing login");
34	      })
35	      .finally(() => {
36	        if (!cancelled) setBooting(false);
37	      });
38	    return () => {
39	      cancelled = true;
40	    };
41	  }, []);
42	
43	  // A poll hit a 401: try to refresh; only truly log out if that fails.
44	  const handleTokenExpired = useCallback(async () => {
45	    if (import.meta.env.DEV) console.info("[app] token expired, refreshing");
46	    try {
47	      const t = await refreshAccessToken();
48	      if (import.meta.env.DEV) console.info("[app] token refreshed");
49	      setToken(t);
50	    } catch {
51	      if (import.meta.env.DEV)
52	        console.info("[app] refresh failed, logging out");
53	      setToken(null);
54	      setError("session_expired");
55	    }
56	  }, []);
57	
58	  if (booting) return null;
59	
60	  if (token) {
61	    return <MapView token={token} onTokenExpired={handleTokenExpired} />;
62	  }
63	
64	  return <LoginButton error={error} />;
65	}
